1	package main
2	
3	// End-to-end regression coverage for the normalize subcommand as users
4	// actually invoke it: logs arrive on stdin, per-line JSON results leave on
5	// stdout, diagnostics leave on stderr, and the exit status summarizes the
6	// run. These tests execute the real compiled binary so the relationship
7	// between per-line results, error output, and the process exit code is
8	// pinned exactly as the shell observes it. Everything runs locally with
9	// scripted input, so the checks are offline and deterministic.
10	
11	import (
12		"bytes"
13		"encoding/json"
14		"fmt"
15		"io"
16		"os"
17		"os/exec"
18		"path/filepath"
19		"strings"
20		"testing"
21		"unicode/utf16"
22		"unicode/utf8"
23	)
24	
25	// escKey renders key as a JSON member name spelled entirely with unicode
26	// escapes (with UTF-16 surrogate pairs above the BMP), so tests can feed a
27	// \uXXXX-encoded key without embedding escape text in the source.
28	func escKey(key string) string {
29		var b strings.Builder
30		b.WriteByte('"')
31		for _, r := range key {
32			for _, u := range utf16.Encode([]rune{r}) {
33				fmt.Fprintf(&b, "\\u%04x", u)
34			}
35		}
36		b.WriteByte('"')
37		return b.String()
38	}
39	
40	// normalizeBin is the compiled relayproof binary shared by all tests in
41	// this package, built once from the current sources.
42	var normalizeBin string
43	
44	func TestMain(m *testing.M) {
45		dir, err := os.MkdirTemp("", "relayproof-cli-test")
46		if err != nil {
47			panic(err)
48		}
49		defer os.RemoveAll(dir)
50	
51		normalizeBin = filepath.Join(dir, "relayproof")
52		build := exec.Command("go", "build", "-o", normalizeBin, ".")
53		if out, err := build.CombinedOutput(); err != nil {
54			panic("building relayproof for CLI tests: " + err.Error() + "\n" + string(out))
55		}
56		os.Exit(m.Run())
57	}
58	
59	// cliResult captures everything the surrounding shell can observe from one
60	// normalize invocation.
61	type cliResult struct {
62		stdout   string
63		stderr   string
64		exitCode int
65	}
66	
67	// runNormalizeCLI executes `relayproof normalize` with stdin fed from r and
68	// records stdout, stderr, and the exit code. A process that cannot be
69	// started at all fails the test rather than masquerading as an exit status.
70	func runNormalizeCLI(t *testing.T, stdin io.Reader) cliResult {
71		t.Helper()
72		return runNormalizeCLIArgs(t, stdin)
73	}
74	
75	// runNormalizeCLIArgs is runNormalizeCLI with explicit extra arguments after
76	// the normalize subcommand, e.g. runNormalizeCLIArgs(t, r, "--source-cidr",
77	// "192.0.2.0/24").
78	func runNormalizeCLIArgs(t *testing.T, stdin io.Reader, args ...string) cliResult {
79		t.Helper()
80		cmd := exec.Command(normalizeBin, append([]string{"normalize"}, args...)...)
81		cmd.Stdin = stdin
82		var stdout, stderr bytes.Buffer
83		cmd.Stdout = &stdout
84		cmd.Stderr = &stderr
85	
86		err := cmd.Run()
87		result := cliResult{stdout: stdout.String(), stderr: stderr.String()}
88		switch {
89		case err == nil:
90			result.exitCode = 0
91		default:
92			exitErr, ok := err.(*exec.ExitError)
93			if !ok {
94				t.Fatalf("normalize process could not run: %v", err)
95			}
96			result.exitCode = exitErr.ExitCode()
97		}
98		return result
99	}
100	
101	// decodeStdoutResults parses stdout as newline-delimited JSON result
102	// objects. Any line that is not a JSON object — help text, a plain-text
103	// notice, a log fragment — fails the test, because stdout must carry
104	// machine-readable results and nothing else.
105	func decodeStdoutResults(t *testing.T, stdout string) []map[string]any {
106		t.Helper()
107		var results []map[string]any
108		decoder := json.NewDecoder(strings.NewReader(stdout))
109		for {
110			var record map[string]any
111			if err := decoder.Decode(&record); err != nil {
112				if err == io.EOF {
113					return results
114				}
115				t.Fatalf("stdout must contain only JSON result objects, got decode error %v after %d records: %q",
116					err, len(results), stdout)
117			}
118			results = append(results, record)
119		}
120	}
121	
122	// eventOf extracts the event object of a successful result.
123	func eventOf(t *testing.T, result map[string]any) map[string]any {
124		t.Helper()
125		event, ok := result["event"].(map[string]any)
126		if !ok {
127			t.Fatalf("result has no event object: %#v", result)
128		}
129		return event
130	}
131	
132	// A healthy run: every log line normalizes, stdout carries one JSON result
133	// per line and nothing else, stderr stays silent, and the process exits 0.
134	// Alias keys must surface under their canonical names, the timestamp must be
135	// converted to UTC, the action trimmed, and unmapped fields must survive in
136	// extra with their JSON types intact.
137	func TestNormalizeCLIAllValidExitsZero(t *testing.T) {
138		input := `{"time":"2026-01-02T08:04:05+08:00","src_ip":"2001:db8::1","event_type":"  login  ","user":" alice ","retries":2,"ok":true}` + "\n" +
139			`{"timestamp":"2026-01-02T00:00:00Z","action":"logout","source_ip":"10.0.0.9","tags":["a","b"],"meta":{"trace":"t-1"}}` + "\n"
140	
141		result := runNormalizeCLI(t, strings.NewReader(input))
142	
143		if result.exitCode != 0 {
144			t.Fatalf("all-valid input must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
145		}
146		if result.stderr != "" {
147			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
148		}
149	
150		results := decodeStdoutResults(t, result.stdout)
151		if len(results) != 2 {
152			t.Fatalf("expected one result per input line, got %#v", results)
153		}
154	
155		first := results[0]
156		if first["line"] != float64(1) || first["ok"] != true {
157			t.Fatalf("first result must report line 1 as ok: %#v", first)
158		}
159		event := eventOf(t, first)
160		if event["timestamp"] != "2026-01-02T00:04:05Z" {
161			t.Fatalf("alias time must land in timestamp converted to UTC, got %v", event["timestamp"])
162		}
163		if event["source_ip"] != "2001:db8::1" {
164			t.Fatalf("alias src_ip must land in source_ip, got %v", event["source_ip"])
165		}
166		if event["action"] != "login" {
167			t.Fatalf("alias event_type must land in action with whitespace trimmed, got %v", event["action"])
168		}
169		extra, ok := event["extra"].(map[string]any)
170		if !ok {
171			t.Fatalf("unmapped fields must be kept in extra: %#v", event)
172		}
173		if extra["user"] != " alice " {
174			t.Fatalf("extra strings must pass through verbatim, got %v", extra["user"])
175		}
176		if extra["retries"] != float64(2) {
177			t.Fatalf("extra numbers must stay numbers, got %#v", extra["retries"])
178		}
179		if extra["ok"] != true {
180			t.Fatalf("extra booleans must stay booleans, got %#v", extra["ok"])
181		}
182	
183		second := results[1]
184		if second["line"] != float64(2) || second["ok"] != true {
185			t.Fatalf("second result must report line 2 as ok: %#v", second)
186		}
187		event = eventOf(t, second)
188		if event["action"] != "logout" || event["source_ip"] != "10.0.0.9" {
189			t.Fatalf("canonical fields must round-trip unchanged: %#v", event)
190		}
191		extra, ok = event["extra"].(map[string]any)
192		if !ok {
193			t.Fatalf("structured extra fields must be kept: %#v", event)
194		}
195		tags, ok := extra["tags"].([]any)
196		if !ok || len(tags) != 2 || tags[0] != "a" || tags[1] != "b" {
197			t.Fatalf("extra arrays must keep their element order and types, got %#v", extra["tags"])
198		}
199		meta, ok := extra["meta"].(map[string]any)
200		if !ok || meta["trace"] != "t-1" {
201			t.Fatalf("extra objects must survive the command entry intact, got %#v", extra["meta"])
202		}
203	}
204	
205	// The key mixed-input case: a field-invalid log between two valid ones. The
206	// bad line gets an ok:false result with an explanatory error and no event,
207	// the surrounding valid lines still succeed in input order, and the process
208	// exits 1 — it must neither stop at the first bad line nor let the trailing
209	// success reset the status to 0. stderr stays empty because the failure is
210	// described by its own result record.
211	func TestNormalizeCLIInvalidLineBetweenValidOnesExitsOne(t *testing.T) {
212		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
213			`{"timestamp":"not-a-time","action":"broken"}` + "\n" +
214			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n"
215	
216		result := runNormalizeCLI(t, strings.NewReader(input))
217	
218		if result.exitCode != 1 {
219			t.Fatalf("one invalid log must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
220		}
221		if result.stderr != "" {
222			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
223		}
224	
225		results := decodeStdoutResults(t, result.stdout)
226		if len(results) != 3 {
227			t.Fatalf("processing must continue past the bad line; expected 3 results, got %#v", results)
228		}
229	
230		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
231			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
232		}
233		if eventOf(t, results[0])["action"] != "first" {
234			t.Fatalf("line 1 event content mismatch: %#v", results[0])
235		}
236	
237		bad := results[1]
238		if bad["line"] != float64(2) || bad["ok"] != false {
239			t.Fatalf("the invalid log must be reported as line 2 with ok=false: %#v", bad)
240		}
241		if _, exists := bad["event"]; exists {
242			t.Fatalf("a failed line must not carry an event: %#v", bad)
243		}
244		message, ok := bad["error"].(string)
245		if !ok || message == "" {
246			t.Fatalf("a failed line must explain itself in error: %#v", bad)
247		}
248		if !strings.Contains(message, "timestamp") {
249			t.Fatalf("the error must name the offending field, got %q", message)
250		}
251	
252		if results[2]["line"] != float64(3) || results[2]["ok"] != true {
253			t.Fatalf("the trailing valid log must still succeed on line 3: %#v", results[2])
254		}
255		if eventOf(t, results[2])["action"] != "last" {
256			t.Fatalf("line 3 event content mismatch: %#v", results[2])
257		}
258	}
259	
260	// Blank lines produce no results but still consume physical line numbers,
261	// and a final complete log without a trailing newline is processed like any
262	// other. The run is clean, so the exit status is 0 and stderr stays empty.
263	func TestNormalizeCLIBlankLinesAndMissingFinalNewline(t *testing.T) {
264		input := "\n" +
265			"   \n" +
266			`{"timestamp":"2026-01-02T00:00:00Z","action":"alpha"}` + "\n" +
267			"\t\n" +
268			`{"timestamp":"2026-01-02T00:00:01Z","action":"omega"}` // no trailing newline
269	
270		result := runNormalizeCLI(t, strings.NewReader(input))
271	
272		if result.exitCode != 0 {
273			t.Fatalf("blank lines and a newline-less tail must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
274		}
275		if result.stderr != "" {
276			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
277		}
278	
279		results := decodeStdoutResults(t, result.stdout)
280		if len(results) != 2 {
281			t.Fatalf("blank lines must not produce results, got %#v", results)
282		}
283		if results[0]["line"] != float64(3) {
284			t.Fatalf("line numbers must count blank physical lines, got %#v", results[0])
285		}
286		if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "alpha" {
287			t.Fatalf("line 3 result mismatch: %#v", results[0])
288		}
289		if results[1]["line"] != float64(5) {
290			t.Fatalf("the final log must keep its physical line number 5, got %#v", results[1])
291		}
292		if results[1]["ok"] != true || eventOf(t, results[1])["action"] != "omega" {
293			t.Fatalf("a final line without newline must normalize normally: %#v", results[1])
294		}
295	}
296	
297	// Empty input — and input holding only blank lines — ends quietly: no
298	// results, no diagnostics, exit status 0.
299	func TestNormalizeCLIEmptyOrBlankOnlyInput(t *testing.T) {
300		cases := []struct {
301			name  string
302			input string
303		}{
304			{"completely empty", ""},
305			{"only blank lines", "\n   \n\t\n"},
306		}
307		for _, tc := range cases {
308			t.Run(tc.name, func(t *testing.T) {
309				result := runNormalizeCLI(t, strings.NewReader(tc.input))
310				if result.exitCode != 0 {
311					t.Fatalf("input without logs must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
312				}
313				if result.stdout != "" {
314					t.Fatalf("no logs means no results on stdout, got %q", result.stdout)
315				}
316				if result.stderr != "" {
317					t.Fatalf("no logs means no diagnostics on stderr, got %q", result.stderr)
318				}
319			})
320		}
321	}
322	
323	// A stdin read failure before any complete log line is a stream-level
324	// problem, not a bad log: the process exits 2, stderr explains the read
325	// failure with the normalize: prefix, and stdout carries no per-line
326	// results — the failure must not be disguised as one log's field error.
327	func TestNormalizeCLIReadErrorExitsTwo(t *testing.T) {
328		// Reading a directory fails deterministically on the first Read, before
329		// any byte of a log line can arrive.
330		dir, err := os.Open(".")
331		if err != nil {
332			t.Fatalf("opening a directory as failing stdin: %v", err)
333		}
334		defer dir.Close()
335	
336		result := runNormalizeCLI(t, dir)
337	
338		if result.exitCode != 2 {
339			t.Fatalf("a stdin read failure must exit 2, got %d (stderr: %q)", result.exitCode, result.stderr)
340		}
341		if result.stdout != "" {
342			t.Fatalf("no complete log line means no results on stdout, got %q", result.stdout)
343		}
344		if !strings.HasPrefix(result.stderr, "normalize: ") {
345			t.Fatalf("the read failure must be reported with the normalize: prefix, got %q", result.stderr)
346		}
347		if !strings.Contains(strings.ToLower(result.stderr), "read") {
348			t.Fatalf("the diagnostic must identify a read failure, got %q", result.stderr)
349		}
350	}
351	
352	// A log line with corrupted characters — invalid UTF-8 bytes or an unpaired
353	// \uXXXX surrogate escape anywhere in the object, including deep inside
354	// unmapped fields — is an ordinary per-line failure: one ok:false record with
355	// the physical line number and a reason that distinguishes the two defects,
356	// no event, valid lines around it still processed in order, exit status 1,
357	// and stderr empty. The failure records themselves must be valid UTF-8 JSON:
358	// corrupted input bytes are never echoed back into the output.
359	func TestNormalizeCLICorruptedCharactersExitOne(t *testing.T) {
360		input := []byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
361			`{"timestamp":"2026-01-02T00:00:00Z","action":"bad` + "\xff\xfe" + `"}` + "\n" +
362			`{"timestamp":"2026-01-02T00:00:00Z","action":"ok","extra":{"deep":["` + "\\uD800" + `"]}}` + "\n" +
363			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n")
364	
365		result := runNormalizeCLI(t, bytes.NewReader(input))
366	
367		if result.exitCode != 1 {
368			t.Fatalf("corrupted log lines must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
369		}
370		if result.stderr != "" {
371			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
372		}
373		if !utf8.ValidString(result.stdout) {
374			t.Fatalf("stdout must be valid UTF-8 even for corrupted input, got %q", result.stdout)
375		}
376	
377		results := decodeStdoutResults(t, result.stdout)
378		if len(results) != 4 {
379			t.Fatalf("processing must continue past corrupted lines; expected 4 results, got %#v", results)
380		}
381		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
382			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
383		}
384	
385		badUTF8 := results[1]
386		if badUTF8["line"] != float64(2) || badUTF8["ok"] != false {
387			t.Fatalf("the invalid-UTF-8 log must fail as line 2: %#v", badUTF8)
388		}
389		if _, exists := badUTF8["event"]; exists {
390			t.Fatalf("a corrupted line must not carry an event: %#v", badUTF8)
391		}
392		msg, _ := badUTF8["error"].(string)
393		if !strings.Contains(msg, "UTF-8") {
394			t.Fatalf("invalid bytes must be reported as UTF-8 corruption, got %q", msg)
395		}
396	
397		badEscape := results[2]
398		if badEscape["line"] != float64(3) || badEscape["ok"] != false {
399			t.Fatalf("the unpaired-escape log must fail as line 3: %#v", badEscape)
400		}
401		if _, exists := badEscape["event"]; exists {
402			t.Fatalf("a corrupted line must not carry an event: %#v", badEscape)
403		}
404		msg, _ = badEscape["error"].(string)
405		if !strings.Contains(msg, "surrogate") {
406			t.Fatalf("an unpaired escape deep in extra must be reported as a surrogate problem, got %q", msg)
407		}
408	
409		if results[3]["line"] != float64(4) || results[3]["ok"] != true {
410			t.Fatalf("the trailing valid log must still succeed on line 4: %#v", results[3])
411		}
412		if eventOf(t, results[3])["action"] != "last" {
413			t.Fatalf("line 4 event content mismatch: %#v", results[3])
414		}
415	}
416	
417	// A duplicate top-level key written with a unicode escape is the same failure
418	// as a literal repeated key. With one such line between legal logs (and a
419	// blank line shifting physical numbers), the CLI must emit per-line JSON
420	// results in order, keep the failure's line number with no event and a reason
421	// that names the field, and still exit 1: trailing valid lines never reset
422	// the status. An escape-only spelling of a standard field is a normal event.
423	func TestNormalizeCLIEscapedDuplicateKeyExitsOne(t *testing.T) {
424		dup := `{"timestamp":"2026-01-02T00:00:00Z","action":"first",` + escKey("action") + `:"second"}`
425		escapedOnly := `{` + escKey("timestamp") + `:"2026-01-02T08:04:05+08:00",` + escKey("action") + `:"ok"}`
426		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
427			dup + "\n" +
428			"  \n" +
429			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n" +
430			escapedOnly
431	
432		result := runNormalizeCLI(t, strings.NewReader(input))
433	
434		if result.exitCode != 1 {
435			t.Fatalf("a duplicate-key line must set exit status 1 even with later valid logs, got %d (stderr: %q)",
436				result.exitCode, result.stderr)
437		}
438		if result.stderr != "" {
439			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
440		}
441	
442		results := decodeStdoutResults(t, result.stdout)
443		if len(results) != 4 {
444			t.Fatalf("blank lines produce no output; expected 4 results, got %#v", results)
445		}
446		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
447			t.Fatalf("leading valid log must succeed on line 1: %#v", results[0])
448		}
449		if eventOf(t, results[0])["action"] != "first" {
450			t.Fatalf("line 1 event content mismatch: %#v", results[0])
451		}
452	
453		bad := results[1]
454		if bad["line"] != float64(2) || bad["ok"] != false {
455			t.Fatalf("the escaped duplicate key must fail as line 2: %#v", bad)
456		}
457		if _, exists := bad["event"]; exists {
458			t.Fatalf("a failed line must not carry an event: %#v", bad)
459		}
460		message, ok := bad["error"].(string)
461		if !ok || message == "" {
462			t.Fatalf("the failed line must explain itself: %#v", bad)
463		}
464		if !strings.Contains(strings.ToLower(message), "duplicate") || !strings.Contains(message, "action") {
465			t.Fatalf("error must identify the duplicate action field, got %q", message)
466		}
467		if strings.Contains(strings.ToLower(message), "conflict") {
468			t.Fatalf("a decoded duplicate key must not be reported as an action conflict: %q", message)
469		}
470	
471		if results[2]["line"] != float64(4) || results[2]["ok"] != true {
472			t.Fatalf("the valid log after the blank line must succeed as line 4: %#v", results[2])
473		}
474		if eventOf(t, results[2])["action"] != "last" {
475			t.Fatalf("line 4 event content must survive in order: %#v", results[2])
476		}
477	
478		if results[3]["line"] != float64(5) || results[3]["ok"] != true {
479			t.Fatalf("an escape-only standard field spelling must succeed as line 5: %#v", results[3])
480		}
481		if eventOf(t, results[3])["timestamp"] != "2026-01-02T00:04:05Z" {
482			t.Fatalf("escaped-only names must normalize like literal names: %#v", results[3])
483		}
484	}
