// isCleanEOF reports whether err marks ordinary end-of-input carrying no
// independent failure reason. A bare io.EOF is clean, and so is any error
// that only wraps that one marker through ordinary single-cause wrapping:
// every leaf reachable through Unwrap is the EOF marker. A combined error
// that joins io.EOF WITH another reason — errors.Join(io.EOF, cause), a
// custom error exposing several Unwrap targets, or either shape behind
// further wrapping — is NOT clean even though errors.Is(err, io.EOF)
// matches, because that second leaf is a genuine read fault. Only leaf
// errors are inspected: intermediate wrapping nodes are structure, not
// causes. The traversal is cycle-safe.
func isCleanEOF(err error) bool {
	if err == nil {
		return false
	}
	clean := true
	var walk func(error, map[error]bool)
	walk = func(e error, seen map[error]bool) {
		if e == nil || !clean {
			return
		}
		// A self-referential Unwrap graph is malformed; never loop on it.
		if !isComparableError(e) {
			// Non-comparable error values cannot be tracked in a map; a tree
			// built from them cannot repeat a node by identity, so descend
			// without recording it.
		} else if seen[e] {
			return
		} else {
			seen[e] = true
		}
		switch u := e.(type) {
		case interface{ Unwrap() error }:
			walk(u.Unwrap(), seen)
		case interface{ Unwrap() []error }:
			for _, child := range u.Unwrap() {
				walk(child, seen)
				if !clean {
					return
				}
			}
		default:
			// A leaf has nothing more to unwrap, so errors.Is here is plain
			// identity: it is either the EOF marker itself or a real cause.
			if !errors.Is(e, io.EOF) {
				clean = false
			}
		}
	}
	walk(err, make(map[error]bool))
	return clean
}

// isComparableError reports whether e can be used as a map key for cycle
// detection. Errors are almost always pointer or comparable struct values;
// a non-comparable concrete type (e.g. one holding a slice) is simply not
// recorded, which is safe because such a value cannot recur by identity.
func isComparableError(e error) (ok bool) {
	defer func() {
		if recover() != nil {
			ok = false
		}
	}()
	var m map[error]bool
	_ = m
	// Probe comparability through a zero-sized map assignment.
	probe := make(map[error]struct{})
	probe[e] = struct{}{}
	return true
}

