// that only wraps that one marker through ordinary single-cause wrapping:
// every leaf reachable through Unwrap is the EOF marker. A combined error
// that joins io.EOF WITH another reason — errors.Join(io.EOF, cause), a
// custom error exposing several Unwrap targets, or either shape behind
// further wrapping — is NOT clean even though errors.Is(err, io.EOF)
// matches, because that second leaf is a genuine read fault. Only leaf
// errors are inspected: intermediate wrapping nodes are structure, not
// causes. The seen set keeps a self-referential Unwrap graph from looping;
// non-comparable error values are descended without recording (such a value
// cannot recur by identity anyway).
func isCleanEOF(err error) bool {
	if err == nil {
		return false
	}
	clean := true
	seen := make(map[any]bool)
	var walk func(error)
	walk = func(e error) {
		if e == nil || !clean {
			return
		}
		if mark(seen, e) {
			return // already visited: a cyclic error graph
		}
		switch u := e.(type) {
		case interface{ Unwrap() error }:
			walk(u.Unwrap())
		case interface{ Unwrap() []error }:
			for _, child := range u.Unwrap() {
				walk(child)
				if !clean {
					return
				}
			}
		default:
			// A leaf has nothing more to unwrap, so errors.Is here is plain
			// identity: it is either the EOF marker itself or a real cause.
			if !errors.Is(e, io.EOF) {
				clean = false
			}
		}
	}
	walk(err)
	return clean
}

// mark records e in seen for cycle detection, reporting whether it was
// already present. A non-comparable dynamic error type (one holding a slice
// or map) cannot be a map key and cannot recur by identity, so it is treated
// as not-yet-seen and the caller descends normally.
func mark(seen map[any]bool, e error) (already bool) {
	defer func() {
		if recover() != nil {
			already = false
		}
	}()
	if seen[e] {
		return true
	}
	seen[e] = true
	return false
}

